INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','كمية انتاج المرزه بالدكسم نوار تكس: دليل متكامل لزيادة الانتاجية - سبيلكم' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كيفية قياس كمية انتاج المرزه للدكسم باستخدام تقنية نوار تكس. دليل مهني فائق التفاصيل للمزارعين العراقيين لتقييم المحاصيل، زيادة الغلة، وتحسين الكفاءة الزراعية في 2024. احصل على معلومات تقنية موثوقة من خبراء الزراعة العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
