INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола таҳлили муфассали нархҳои парвариши сабзавот бо системаи напур дар ҷога оварда шудааст. Равонамоии комил барои деҳқонон бо нигоҳдошти маънои tekniky ва истилоҳотҳои AFP барои кам кардани хараҷот ва зиёд кардани sammonа.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
